import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.DlQ8ZhpE.js";const k=JSON.parse('{"title":"fiber.dev.abc.spec.gateway.hitl.slack","description":"","frontmatter":{},"headers":[],"relativePath":"dev/abc/spec/gateway/hitl.slack.md","filePath":"dev/abc/spec/gateway/hitl.slack.md"}'),n={name:"dev/abc/spec/gateway/hitl.slack.md"};function o(d,e,l,c,r,p){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="fiber-dev-abc-spec-gateway-hitl-slack" tabindex="-1">fiber.dev.abc.spec.gateway.hitl.slack <a class="header-anchor" href="#fiber-dev-abc-spec-gateway-hitl-slack" aria-label="Permalink to &quot;fiber.dev.abc.spec.gateway.hitl.slack&quot;">​</a></h1><p>@desc: Out-of-Band (OOB) HITL Bridge, State Envelope &amp; Slack Socket Mode Specification</p><h2 id="_1-cryptographic-state-envelope-oob-gate-architecture" tabindex="-1">1. Cryptographic State Envelope &amp; OOB Gate Architecture <a class="header-anchor" href="#_1-cryptographic-state-envelope-oob-gate-architecture" aria-label="Permalink to &quot;1. Cryptographic State Envelope &amp; OOB Gate Architecture&quot;">​</a></h2><p>When <code>MCPServerConnector</code> parks a high-risk call (<code>HTTP 202</code>), <code>OutOfBandApprovalBridge</code> and <code>SlackHitlBridge</code> coordinate human attestation without relying on a centralized approval database.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[MCP_PHASE_YIELD Event] ──► [SlackHitlBridge]</span></span>\n<span class="line"><span>                              └─ Mint Ed25519-Signed `ApprovalStateEnvelope` &amp; Post Block-Kit Card</span></span>\n<span class="line"><span>                                   │</span></span>\n<span class="line"><span>                                   ▼ (Operator Clicks Approve / Deny in Slack)</span></span>\n<span class="line"><span>[OutOfBandApprovalBridge.handle_slack_interaction]</span></span>\n<span class="line"><span>  ├─ Gate 1 (Transport): Verify Slack `v0=` HMAC-SHA256 &amp; 300s replay drift window</span></span>\n<span class="line"><span>  ├─ Gate 2 (Envelope):  Verify NodeSigner Ed25519 signature &amp; `exp` TTL on `ApprovalStateEnvelope`</span></span>\n<span class="line"><span>  ├─ Gate 3 (Replay):    Consume signature in single-use `_consumed_tokens` cache</span></span>\n<span class="line"><span>  └─ Gate 4 (Identity):  Map external user -&gt; SPIFFE ID &amp; publish `McpIntentDispatch` (`AttestedResumeResult`)</span></span>\n<span class="line"><span>       │</span></span>\n<span class="line"><span>       ▼</span></span>\n<span class="line"><span>[ValidatorService &amp; PreflightGuard.verify_and_pop]</span></span>\n<span class="line"><span>  └─ Decrypt Admin AES-GCM Vault -&gt; Verify 6-Digit TOTP (or 1-Click SPIFFE) -&gt; Release Stashed Payload</span></span></code></pre></div><h3 id="_1-1-wire-contracts-fiber-gateway-bridge-channel-oob" tabindex="-1">1.1. Wire Contracts (<code>fiber.gateway.bridge.channel.oob</code>) <a class="header-anchor" href="#_1-1-wire-contracts-fiber-gateway-bridge-channel-oob" aria-label="Permalink to &quot;1.1. Wire Contracts (`fiber.gateway.bridge.channel.oob`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Contract Model</th><th>Core Fields</th><th>Optional Extension Slots</th><th>Security Role</th></tr></thead><tbody><tr><td><strong><code>ApprovalStateEnvelope</code></strong></td><td><code>handle_id</code>, <code>target_id</code>, <code>prompt_id</code>, <code>exp</code></td><td><code>node_fp</code>, <code>bridge_id</code>, <code>require_totp</code>, <code>extra</code></td><td>Embedded in Slack button values; Canonical JSON signed with node <code>Ed25519</code> key to prevent handle hijacking and cross-node collisions (<code>node_fp</code>).</td></tr><tr><td><strong><code>AttestedResumeResult</code></strong></td><td><code>value</code> (OTP), <code>attested_user_id</code> (SPIFFE)</td><td><code>override_args</code>, <code>lease_ttl_sec</code>, <code>quorum_sigs</code>, <code>comment</code></td><td>Injected into <code>mcp.intent.queue.&lt;target_id&gt;</code> upon verification; omits <code>None</code> fields on the wire for 100% backward compatibility.</td></tr><tr><td><strong><code>McpIntentDispatch</code></strong></td><td><code>handle_id</code>, <code>action</code> (<code>RESUME</code></td><td><code>FORCE_ROLLBACK</code>)</td><td><code>prompt_id</code>, <code>result</code>, <code>reason</code></td></tr></tbody></table><h3 id="_1-2-attestation-modes-totp-vs-1-click-button" tabindex="-1">1.2. Attestation Modes (<code>TOTP</code> vs. <code>1-Click Button</code>) <a class="header-anchor" href="#_1-2-attestation-modes-totp-vs-1-click-button" aria-label="Permalink to &quot;1.2. Attestation Modes (`TOTP` vs. `1-Click Button`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>Trigger Syntax</th><th>Slack Block-Kit UI</th><th>Validator Check (<code>ValidatorService</code>)</th></tr></thead><tbody><tr><td><strong>6-Digit TOTP</strong> <em>(Default)</em></td><td>`&quot;RESTRICTED_TOPIC</td><td>DROP&quot;`</td><td>Renders <code>fiber_totp_block</code> (<code>plain_text_input</code>) + <strong>Approve / Deny</strong> buttons.</td></tr><tr><td><strong>1-Click Button</strong></td><td>`&quot;button:prod_secrets</td><td>DELETE&quot;`</td><td>Omits TOTP input; renders <strong>Approve &amp; Resume</strong> / <strong>Deny &amp; Rollback</strong> buttons only.</td></tr></tbody></table><hr><h2 id="_2-node-keychain-admin-vault-provisioning-fiber-sign" tabindex="-1">2. Node Keychain &amp; Admin Vault Provisioning (<code>fiber sign</code>) <a class="header-anchor" href="#_2-node-keychain-admin-vault-provisioning-fiber-sign" aria-label="Permalink to &quot;2. Node Keychain &amp; Admin Vault Provisioning (`fiber sign`)&quot;">​</a></h2><p>Both TOTP and 1-Click modes require the operator&#39;s mapped SPIFFE ID to be enrolled in the local AES-GCM SQLite vault (<code>deploy_audit.sqlite</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fiber</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                          # Initialize Ed25519 node identity &amp; local_cipher.key</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fiber</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enroll</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spiffe://self/fiber</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Enroll admin SPIFFE ID &amp; render terminal TOTP QR code</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fiber</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spiffe://self/fiber</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Test AES-GCM decryption &amp; 6-digit RFC-6238 code</span></span></code></pre></div><hr><h2 id="_3-slack-socket-mode-setup" tabindex="-1">3. Slack Socket Mode Setup <a class="header-anchor" href="#_3-slack-socket-mode-setup" aria-label="Permalink to &quot;3. Slack Socket Mode Setup&quot;">​</a></h2><p><code>SlackHitlBridge</code> operates over <strong>100% Outbound Socket Mode</strong> (zero inbound firewall ports required) and replaces interactive cards in-place (<code>replace_original: True</code>) with an immutable <strong>Zero-Trust Attestation Receipt</strong> upon resolution.</p><h3 id="_3-1-1-click-app-provisioning-via-manifest-cli" tabindex="-1">3.1. 1-Click App Provisioning via Manifest CLI <a class="header-anchor" href="#_3-1-1-click-app-provisioning-via-manifest-cli" aria-label="Permalink to &quot;3.1. 1-Click App Provisioning via Manifest CLI&quot;">​</a></h3><p>Instead of configuring Socket Mode, Interactivity, and OAuth scopes manually, use the built-in manifest provisioner (<code>fiber.plane.ops.channel.slack</code>), which pre-configures <code>socket_mode_enabled: true</code>, <code>interactivity: true</code>, and required bot scopes (<code>chat:write</code>, <code>chat:write.public</code>, <code>channels:read</code>, <code>channels:join</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Print 3-step setup guide &amp; open pre-populated Slack App Manifest URL in browser (or `json` for raw manifest)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fiber</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ops</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> channel.slack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> guide</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --open</span></span></code></pre></div><ol><li><strong>Create App:</strong> Select your workspace in the opened browser tab and click <strong>Create</strong>.</li><li><strong>App-Level Token (<code>xapp-...</code>):</strong> Navigate to <strong>Basic Information</strong> → <strong>App-Level Tokens</strong> → <strong>Generate Token and Scopes</strong>, add <code>connections:write</code>, and copy <code>xapp-1-...</code>.</li><li><strong>Bot Token (<code>xoxb-...</code>):</strong> Navigate to <strong>Install App</strong> → <strong>Install to Workspace</strong> and copy <code>xoxb-...</code>.</li></ol><h3 id="_3-2-environment-variables-env" tabindex="-1">3.2. Environment Variables (<code>.env</code>) <a class="header-anchor" href="#_3-2-environment-variables-env" aria-label="Permalink to &quot;3.2. Environment Variables (`.env`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>FIBER_SLACK_BOT_TOKEN</code></td><td><strong>Yes</strong> (Live)</td><td>Bot User OAuth Token (<code>xoxb-...</code>) for posting Block-Kit prompts.</td></tr><tr><td><code>FIBER_SLACK_APP_TOKEN</code></td><td><strong>Yes</strong> (Socket)</td><td>App-Level Token (<code>xapp-...</code>) for outbound Socket Mode WebSocket.</td></tr><tr><td><code>FIBER_SLACK_CHANNEL_ID</code></td><td><strong>Yes</strong> (Live)</td><td>Target Slack Channel ID (e.g., <code>C0A9L79HY57</code>). Auto-discovered during interactive <code>tester</code> runs.</td></tr><tr><td><code>FIBER_SLACK_USER_ID</code></td><td>Optional</td><td>Slack User ID mapped to enrolled SPIFFE ID (<code>*</code> fallback supported in dev).</td></tr><tr><td><code>FIBER_SLACK_SIGNING_SECRET</code></td><td>Optional</td><td>Webhook HMAC secret <em>(auto-derived from node <code>Ed25519</code> pubkey if omitted)</em>.</td></tr></tbody></table><hr><h2 id="_4-verification-e2e-testing" tabindex="-1">4. Verification &amp; E2E Testing <a class="header-anchor" href="#_4-verification-e2e-testing" aria-label="Permalink to &quot;4. Verification &amp; E2E Testing&quot;">​</a></h2><h3 id="_4-1-isolated-channel-token-smoke-test-ops-channel-slack" tabindex="-1">4.1. Isolated Channel &amp; Token Smoke Test (<code>ops.channel.slack</code>) <a class="header-anchor" href="#_4-1-isolated-channel-token-smoke-test-ops-channel-slack" aria-label="Permalink to &quot;4.1. Isolated Channel &amp; Token Smoke Test (`ops.channel.slack`)&quot;">​</a></h3><p>Verifies Slack Socket Mode connectivity, auto-corrects swapped <code>xoxb</code>/<code>xapp</code> tokens, interactively discovers and joins public channels (<code>conversations.list</code> / <code>conversations.join</code>), and validates local RFC-6238 TOTP against <code>deploy_audit.sqlite</code> without booting full MCP workers:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Interactive 1-Click Button round-trip test (auto-discovers &amp; joins channel if --channel is omitted)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fiber</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ops</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> channel.slack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bot-token</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;xoxb-...&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --app-token</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;xapp-...&quot;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Interactive 6-Digit TOTP verification round-trip test</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fiber</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ops</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> channel.slack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bot-token</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;xoxb-...&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --app-token</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;xapp-...&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --totp</span></span></code></pre></div><h3 id="_4-2-full-gateway-pre-flight-e2e-suite-hitl-slack" tabindex="-1">4.2. Full Gateway Pre-Flight E2E Suite (<code>hitl.slack</code>) <a class="header-anchor" href="#_4-2-full-gateway-pre-flight-e2e-suite-hitl-slack" aria-label="Permalink to &quot;4.2. Full Gateway Pre-Flight E2E Suite (`hitl.slack`)&quot;">​</a></h3><p>Validates the complete MCP Gateway pipeline across both <strong>Live Slack Socket Mode</strong> (when <code>FIBER_SLACK_BOT_TOKEN</code> and <code>FIBER_SLACK_APP_TOKEN</code> are present) and <strong>Local Webhook Emulation</strong> (offline CI/CD):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Phase 1 (Dual Guard Arming) -&gt; Phase 2 (Safe 200 OK) -&gt; Phase 3 (Network TOTP) -&gt; Phase 4 (Stdio Zero-Spawn 1-Click)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fiber</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> e2e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway.hitl.slack</span></span></code></pre></div>',30)])])}const g=t(n,[["render",o]]);export{k as __pageData,g as default};
